@php
$workflowService=app(\App\Services\ManuscriptWorkflowService::class);
$rows=$workflowService->scope(\App\Models\Article::query(),auth()->user())->leftJoin('manuscript_workflows','articles.id','=','manuscript_workflows.article_id')->selectRaw("coalesce(manuscript_workflows.stage, articles.status) as stage, count(*) as total")->groupByRaw('coalesce(manuscript_workflows.stage, articles.status)')->pluck('total','stage');
$groups=auth()->user()->hasAnyRole('editor','admin','super-admin')?[
'New manuscripts'=>['submitted'],'Initial check pending'=>['initial_check'],'Plagiarism check'=>['plagiarism_check'],'Editorial screening'=>['editorial_screening'],'Reviewer assignment'=>['reviewer_assignment'],'Under review'=>['under_review','reviewer_recheck'],'Revision submitted'=>['revision_submitted'],'Final decision pending'=>['editor_recheck'],'Accepted'=>['accepted','approved'],'Rejected'=>['rejected'],
]:['Draft'=>['draft'],'Submitted'=>['submitted'],'Under check'=>['initial_check','plagiarism_check','editorial_screening'],'Under review'=>['reviewer_assignment','under_review','reviewer_recheck'],'Revision required'=>['minor_revision','major_revision','returned','revision_required'],'Accepted'=>['accepted','approved','copyediting'],'Rejected'=>['rejected'],'Proofing'=>['proofing','author_corrections','final_proof_approved','metadata_verified','article_id_generated','doi_pending','doi_submitted','doi_registered','ready_to_publish'],'Published'=>['published','indexing','indexed','archived']];
@endphp
<div class="workflow-metrics">@foreach($groups as $label=>$stages)<a class="portal-card" href="{{ route('workflow.index',['stages'=>$stages]) }}"><small>{{ $label }}</small><strong>{{ collect($stages)->sum(fn($stage)=>$rows[$stage]??0) }}</strong></a>@endforeach</div>
